export interface IParsedPayload {
    target: string;
    openPorts: Array<number>;
}

let parsedPayload: IParsedPayload;

async function init() {
    const result = await fetch("https://www.example.com/network_scan_result");
    parsedPayload = (await result.json()).payload as IParsedPayload;
}

function main() {
    init();

    const parser = new QyParser(parsedPayload.target, parsedPayload.openPorts);
    const anomalyDetector = new AnomalyDetector(parser);
    const networkScanResult: string = await anomalyDetector.analyzeNetworkScan();

    console.log(`Analyzing the network scan result for anomalies:\n\n${networkScanResult}`);
}

main();
```

